{"file_path": "/src/@user/slides.js", "content": "const _intro = function intro(md){return( md`# Slide Deck
## Built with @tomlarkworthy/slides

Click to focus, then use arrow keys to navigate.
Press **F** for fullscreen, **O** for overview.
` )};

const _about = function about(md){return( md`## About This Deck

- Each slide is a **live cell** in this module
- Edit a cell → its slide updates instantly
- Add inputs on slides that drive the notebook
- Reorder slides in the \`deck\` cell's \`slides:\` array
` )};

const _demo_chart = function demo_chart(Plot){return(
  Plot.plot({
    width: 640,
    height: 360,
    marks: [
      Plot.lineY(
        Array.from({length: 50}, (_, i) => Math.sin(i / 5) + Math.random() * 0.3),
        {stroke: "#4e79a7", strokeWidth: 3}
      ),
      Plot.ruleY([0])
    ],
    y: {label: "value"},
    x: {label: "index"}
  })
)};

const _demo_chart_title = function demo_chart_title(md){return( md`## Charts Work Too` )};

const _closing = function closing(md){return( md`# Thanks!

Edit the cells in \`@user/slides\` to customize this deck.

Add new slides by creating new cells and adding them to the \`slides:\` array.
` )};

const _deck = function deck(slideshow, runtime, invalidation){return(
  slideshow(runtime, {
    invalidation,
    slides: [
      {cell: "intro", layout: "central"},
      {cell: "about", layout: "upper"},
      {cell: ["demo_chart_title", "demo_chart"], layout: "columns", ratios: [1, 2]},
      {cell: "closing", layout: "central"}
    ],
    width: 1600,
    height: 900,
    transition: "slide",
    builder: true,
    filename: "slides.html"
  })
)};

export default function define(runtime, observer) {
  const main = runtime.module();
  const $def = (pid, name, deps, fn) => main.variable(observer(name)).define(name, deps, fn).pid = pid;
  $def("_intro", "intro", ["md"], _intro);
  $def("_about", "about", ["md"], _about);
  $def("_demo_chart", "demo_chart", ["Plot"], _demo_chart);
  $def("_demo_chart_title", "demo_chart_title", ["md"], _demo_chart_title);
  $def("_closing", "closing", ["md"], _closing);
  $def("_deck", "deck", ["slideshow", "runtime", "invalidation"], _deck);
  main.define("module @tomlarkworthy/slides", async () => runtime.module((await import("/@tomlarkworthy/slides.js?v=4")).default));
  main.define("slideshow", ["module @tomlarkworthy/slides", "@variable"], (_, v) => v.import("slideshow", _));
  main.define("module @tomlarkworthy/runtime-sdk", async () => runtime.module((await import("/@tomlarkworthy/runtime-sdk.js?v=4")).default));
  main.define("runtime", ["module @tomlarkworthy/runtime-sdk", "@variable"], (_, v) => v.import("runtime", _));
  return main;
}"}
